#!/bin/bash
# =============================================================================
# environment-setup.sh — environment layer (VM provisioning, heavy installs, first time only)
# Generated by the remote-setup skill. This file "does nothing just by being committed to the repository".
# Enable it in claude.ai/code → environment dialog → Setup script field by [pasting this whole content].
#
# Behavior (official): runs as root when a new cloud session starts, before Claude Code starts.
# Afterwards the filesystem is snapshotted and cached for about 7 days (skipped from then on).
# Changing the Setup script or the network settings rebuilds the cache.
#
# Constraints:
# - Write it assuming the repository does not exist yet (self-contained, install into fixed paths)
# - Within about 5 minutes / exit code 0 is mandatory (add `|| true` to non-essential steps)
# - Only files survive in the cache (started processes do not)
# =============================================================================
# Because "exit code 0 is mandatory", set -e / set -u are not used. Every step gets || true.
export DEBIAN_FRONTEND=noninteractive

apt-get update -qq || true

# --- ▼▼▼ Repository-specific heavy installs (rewrite this part when generating) ▼▼▼ ---
# What goes here: apt packages / global CLIs / heavy packages into system pip /
# fetching prebuilt binaries. Install into repo-independent fixed paths.
#
# Example (apt): apt-get install -y -qq libgl1 libglu1-mesa || true
# Example (global CLI): npm install -g @google/clasp || true
# Example (heavy Python package into the system; visible from the session layer's venv
#     via --system-site-packages):
#   pip install --break-system-packages build123d || true
# --- ▲▲▲ End of repository-specific steps ▲▲▲ ---------------------------------

exit 0
